'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { createDOM, NodeFilter } = require('./test-dom-helper');
const { finder } = require('../finder');

const SMART_BLUR_PRESETS = {
  email:      /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
  ssn:        /\b\d{3}-?\d{2}-?\d{4}\b/g,
  creditCard: /\b(?:\d[ -]*?){13,19}\b/g,
  phone:      /(?:\+\d{1,3}[\s.-]?\d{2,5}[\s.-]?\d{3,4}[\s.-]?\d{3,4}|\b0\d{1,4}[\s.-]?\d{3,4}[\s.-]?\d{3,4}|\(\d{3}\)[\s.-]?\d{3}[\s.-]?\d{4}|\b\d{3}[\s.-]\d{3}[\s.-]\d{4}|\b\d{10,11})\b/g,
  ipAddress:  /\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\b/g,
};

const SMART_BLUR_EXCLUDE = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'IFRAME', 'TEXTAREA', 'INPUT', 'SELECT', 'OPTION']);

function findTextMatches(text, patterns) {
  const ranges = [];
  for (let i = 0; i < patterns.length; i++) {
    let pat = patterns[i];
    if (!pat.global) pat = new RegExp(pat.source, pat.flags + 'g');
    pat.lastIndex = 0;
    let match = pat.exec(text);
    while (match !== null) {
      ranges.push({ start: match.index, end: match.index + match[0].length });
      match = pat.exec(text);
    }
  }
  ranges.sort((a, b) => a.start - b.start);
  const merged = [];
  for (let j = 0; j < ranges.length; j++) {
    const r = ranges[j];
    const last = merged[merged.length - 1];
    if (last && r.start <= last.end) {
      last.end = Math.max(last.end, r.end);
    } else {
      merged.push({ start: r.start, end: r.end });
    }
  }
  return merged;
}

function applySmartBlur(root, doc) {
  const document = doc || root.ownerDocument;
  const patterns = Object.values(SMART_BLUR_PRESETS).map(p => new RegExp(p.source, p.flags));

  const walker = document.createTreeWalker(root, 4 /* SHOW_TEXT */, {
    acceptNode: (node) => {
      if (!node.parentElement) return 2 /* FILTER_REJECT */;
      if (SMART_BLUR_EXCLUDE.has(node.parentElement.tagName)) return 2 /* FILTER_REJECT */;
      if (node.parentElement.closest && node.parentElement.closest('[data-qa-blur]')) return 2 /* FILTER_REJECT */;
      if (!node.textContent || !node.textContent.trim()) return 2 /* FILTER_REJECT */;
      return 1 /* FILTER_ACCEPT */;
    }
  });

  const textNodes = [];
  while (walker.nextNode()) textNodes.push(walker.currentNode);

  for (let i = 0; i < textNodes.length; i++) {
    const tNode = textNodes[i];
    const text = tNode.textContent || '';
    const matches = findTextMatches(text, patterns);
    if (matches.length === 0) continue;

    const frag = document.createDocumentFragment();
    let lastEnd = 0;
    for (let m = 0; m < matches.length; m++) {
      const range = matches[m];
      if (range.start > lastEnd) {
        frag.appendChild(document.createTextNode(text.slice(lastEnd, range.start)));
      }
      const span = document.createElement('span');
      span.className = 'qa-smart-blur';
      span.setAttribute('data-qa-blur', 'regex');
      span.style.setProperty('filter', 'blur(10px)');
      span.style.setProperty('display', 'inline-block');
      span.textContent = text.slice(range.start, range.end);
      frag.appendChild(span);
      lastEnd = range.end;
    }
    if (lastEnd < text.length) {
      frag.appendChild(document.createTextNode(text.slice(lastEnd)));
    }
    if (tNode.parentNode) {
      tNode.parentNode.replaceChild(frag, tNode);
    }
  }

  const inputs = Array.from(root.querySelectorAll ? root.querySelectorAll('input, textarea') : []);
  for (let k = 0; k < inputs.length; k++) {
    const inp = inputs[k];
    if (inp.getAttribute && inp.getAttribute('data-qa-blur')) continue;
    const val = inp.value;
    if (!val) continue;
    if (findTextMatches(val, patterns).length > 0) {
      inp.style.setProperty('filter', 'blur(10px)');
      inp.setAttribute('data-qa-blur', 'input');
    }
  }

  return function unblur() {
    const spans = Array.from(root.querySelectorAll ? root.querySelectorAll('span[data-qa-blur="regex"]') : []);
    for (let s = 0; s < spans.length; s++) {
      const sp = spans[s];
      const txt = document.createTextNode(sp.textContent || '');
      const parent = sp.parentNode;
      if (parent) {
        parent.replaceChild(txt, sp);
        if (parent.normalize) parent.normalize();
      }
    }
    const blurredInputs = Array.from(root.querySelectorAll ? root.querySelectorAll('[data-qa-blur="input"]') : []);
    for (let b = 0; b < blurredInputs.length; b++) {
      blurredInputs[b].style.removeProperty('filter');
      blurredInputs[b].removeAttribute('data-qa-blur');
    }
  };
}

// ── Test Suite 1: Smart Blur Adversarial Harness ─────────────────────────────

test('adversarial smart blur: IPv4 boundaries and octet validation', () => {
  const ipPat = [new RegExp(SMART_BLUR_PRESETS.ipAddress.source, SMART_BLUR_PRESETS.ipAddress.flags)];

  // Valid IPv4 boundary values
  assert.strictEqual(findTextMatches('0.0.0.0', ipPat).length, 1);
  assert.strictEqual(findTextMatches('255.255.255.255', ipPat).length, 1);
  assert.strictEqual(findTextMatches('127.0.0.1', ipPat).length, 1);

  // Invalid IPv4 values exceeding 255 or malformed
  assert.strictEqual(findTextMatches('999.999.999.999', ipPat).length, 0);
  assert.strictEqual(findTextMatches('256.0.0.1', ipPat).length, 0);
  assert.strictEqual(findTextMatches('1.256.0.1', ipPat).length, 0);
  assert.strictEqual(findTextMatches('1.0.0.256', ipPat).length, 0);
});

test('adversarial smart blur: malformed vs valid email addresses', () => {
  const emailPat = [new RegExp(SMART_BLUR_PRESETS.email.source, SMART_BLUR_PRESETS.email.flags)];

  // Valid complex emails
  assert.strictEqual(findTextMatches('user+label@example.co.uk', emailPat).length, 1);
  assert.strictEqual(findTextMatches('john.doe_42@sub-domain.org', emailPat).length, 1);

  // Malformed emails that must NOT match
  assert.strictEqual(findTextMatches('user@', emailPat).length, 0);
  assert.strictEqual(findTextMatches('@example.com', emailPat).length, 0);
  assert.strictEqual(findTextMatches('user@domain', emailPat).length, 0);
  assert.strictEqual(findTextMatches('user@.com', emailPat).length, 0);
  assert.strictEqual(findTextMatches('user@domain.c', emailPat).length, 0);
  assert.strictEqual(findTextMatches('user@domain.123', emailPat).length, 0);
});

test('adversarial smart blur: SSNs and credit card boundary lengths', () => {
  const ssnPat = [new RegExp(SMART_BLUR_PRESETS.ssn.source, SMART_BLUR_PRESETS.ssn.flags)];
  const ccPat  = [new RegExp(SMART_BLUR_PRESETS.creditCard.source, SMART_BLUR_PRESETS.creditCard.flags)];

  // SSNs
  assert.strictEqual(findTextMatches('123-45-6789', ssnPat).length, 1);
  assert.strictEqual(findTextMatches('123456789', ssnPat).length, 1);
  assert.strictEqual(findTextMatches('123-456-789', ssnPat).length, 0);
  assert.strictEqual(findTextMatches('12-345-6789', ssnPat).length, 0);

  // Credit cards (13 to 19 digits)
  assert.strictEqual(findTextMatches('4123456789012', ccPat).length, 1); // 13 digits
  assert.strictEqual(findTextMatches('3782 822463 10005', ccPat).length, 1); // 15 digits Amex
  assert.strictEqual(findTextMatches('4532-0150-1234-5678', ccPat).length, 1); // 16 digits
  assert.strictEqual(findTextMatches('123456789012', ccPat).length, 0); // 12 digits (too short)
  assert.strictEqual(findTextMatches('12345678901234567890', ccPat).length, 0); // 20 digits (too long)
});

test('adversarial smart blur: deeply nested DOM, empty text nodes, overlapping matches, and 100% clean unblur', () => {
  const { document } = createDOM();

  // 30 levels of nesting
  let curr = document.body;
  for (let i = 0; i < 30; i++) {
    const d = document.createElement('div');
    curr.appendChild(d);
    curr = d;
  }

  // Node with overlapping sensitive patterns
  const p = document.createElement('p');
  const expectedOriginal = 'Account contact 192.168.1.1@domain.com, card 4111-2222-3333-4444, ssn 123-45-6789-extra';
  p.textContent = expectedOriginal;
  curr.appendChild(p);

  // Add empty text node and whitespace-only text node
  curr.appendChild(document.createTextNode(''));
  curr.appendChild(document.createTextNode('   \n\t  '));

  const initialText = document.body.textContent;
  const initialChildCount = p.childNodes.length;
  assert.strictEqual(initialChildCount, 1);

  // Execute blur
  const unblur = applySmartBlur(document.body, document);

  const spans = document.body.querySelectorAll('span[data-qa-blur="regex"]');
  assert.ok(spans.length >= 2, 'Should redact detected sensitive elements');
  assert.ok(p.childNodes.length > 1, 'p should be split into text and span nodes');

  // Execute unblur
  unblur();

  const spansAfter = document.body.querySelectorAll('span[data-qa-blur="regex"]');
  assert.strictEqual(spansAfter.length, 0, 'All blurred spans must be removed');
  assert.strictEqual(p.textContent, expectedOriginal, 'Text content must match 100% exactly');
  assert.strictEqual(document.body.textContent, initialText, 'Full body text content must match 100% exactly');
  assert.strictEqual(p.childNodes.length, 1, 'DOM normalize must merge adjacent text nodes back to 1 node');
});

