test('adversarial finder: duplicate class names across repeated structures', () => {
  const { document } = createDOM();
  for (let r = 0; r < 4; r++) {
    const row = document.createElement('div');
    row.className = 'row container';
    for (let c = 0; c < 3; c++) {
      const btn = document.createElement('button');
      btn.className = 'btn primary active';
      btn.textContent = `Btn ${r}-${c}`;
      row.appendChild(btn);
    }
    document.body.appendChild(row);
  }

  // Target row 2, col 1
  const target = document.body.children[2].children[1];
  const sel = finder(target, { root: document.body });

  const matched = document.body.querySelectorAll(sel);
  assert.strictEqual(matched.length, 1, 'Generated selector must match exactly 1 element');
  assert.strictEqual(matched[0], target, 'Matched element must be the exact target');
});

