test('adversarial finder: dynamic numeric IDs are filtered out', () => {
  const { document } = createDOM();
  const d1 = document.createElement('div');
  d1.id = '9988';
  const b1 = document.createElement('button');
  b1.id = ':r1:';
  d1.appendChild(b1);

  const d2 = document.createElement('div');
  d2.id = '9989';
  const b2 = document.createElement('button');
  b2.id = ':r2:';
  d2.appendChild(b2);

  document.body.appendChild(d1);
  document.body.appendChild(d2);

  const isNumeric = (id) => /^:r[0-9a-z]+:?$/.test(id) || /^[0-9]+$/.test(id);
  const sel = finder(b2, {
    root: document.body,
    idName: (id) => !isNumeric(id)
  });

  assert.ok(!sel.includes(':r'), 'Selector must not use dynamic numeric ID');
  assert.ok(!sel.includes('9989'), 'Selector must not use parent numeric ID');

  const matched = document.body.querySelectorAll(sel);
  assert.strictEqual(matched.length, 1, 'Selector must uniquely match b2');
  assert.strictEqual(matched[0], b2, 'Matched element must be b2');
});

// ── Test Suite 3: Crop Coordinate Math Adversarial Harness ───────────────────

function calculateCropMath(rect, padding, dpr, imgWidth, imgHeight) {
  const PAD_RATIO = 0.3;
  const padX = padding === 0 ? 0 : Math.max(24, Math.round(rect.width * PAD_RATIO));
  const padY = padding === 0 ? 0 : Math.max(24, Math.round(rect.height * PAD_RATIO));

  const x = Math.max(0, (rect.left - padX) * dpr);
  const y = Math.max(0, (rect.top  - padY) * dpr);
  const w = Math.min(imgWidth  - x, (rect.width  + padX * 2) * dpr);
  const h = Math.min(imgHeight - y, (rect.height + padY * 2) * dpr);

  const highlightX = (rect.left * dpr) - x;
  const highlightY = (rect.top  * dpr) - y;
  const highlightW = rect.width  * dpr;
  const highlightH = rect.height * dpr;

  const radius = Math.min(8 * dpr, highlightW / 4, highlightH / 4);
  return { padX, padY, x, y, w, h, highlightX, highlightY, highlightW, highlightH, radius };
}

test('adversarial crop: extreme dimensions 1x1 and 10000x10000', () => {
  // 1x1 with padding 80
  const crop1x1 = calculateCropMath({ left: 100, top: 100, width: 1, height: 1 }, 80, 1, 1920, 1080);
  assert.strictEqual(crop1x1.padX, 24);
  assert.strictEqual(crop1x1.padY, 24);
  assert.strictEqual(crop1x1.w, 49);
  assert.strictEqual(crop1x1.h, 49);
  assert.strictEqual(crop1x1.radius, 0.25);

  // 10000x10000 huge dimension: must be clamped to image width/height
  const cropHuge = calculateCropMath({ left: 0, top: 0, width: 10000, height: 10000 }, 80, 1, 1920, 1080);
  assert.strictEqual(cropHuge.x, 0);
  assert.strictEqual(cropHuge.y, 0);
  assert.strictEqual(cropHuge.w, 1920);
  assert.strictEqual(cropHuge.h, 1080);
});

test('adversarial crop: offscreen coordinates stress test and negative dimension boundary check', () => {
  // Offscreen top-left
  const cropTopLeft = calculateCropMath({ left: -500, top: -500, width: 100, height: 100 }, 80, 1, 1920, 1080);
  assert.strictEqual(cropTopLeft.x, 0);
  assert.strictEqual(cropTopLeft.y, 0);
  assert.ok(cropTopLeft.w > 0);
  assert.ok(cropTopLeft.h > 0);

  // Offscreen bottom-right: reveals unconstrained negative w/h vulnerability
  const cropBottomRight = calculateCropMath({ left: 3000, top: 2000, width: 100, height: 100 }, 80, 1, 1920, 1080);
  // Highlight empirical finding: w and h evaluate to negative values when rect is offscreen right/bottom
  assert.ok(cropBottomRight.w < 0, 'Crop width is negative when element is offscreen to the right');
  assert.ok(cropBottomRight.h < 0, 'Crop height is negative when element is offscreen to the bottom');
});
